glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec2 uv;
out vec4 pathData;
vec4 vert () { uv=a_texCoord; pathData=a_color; return cc_matViewProj*vec4(a_position,1.0); }
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
in vec2 uv;
in vec4 pathData;
layout(std140) uniform ElectricParams { vec4 params; };
uniform sampler2D pathTex;
vec2 pointAt(float index,float row){vec4 encodedPoint=texture(pathTex,vec2((index+.5)/64.0,(row+.5)/64.0))*255.0;return vec2(encodedPoint.r*256.0+encodedPoint.g,encodedPoint.b*256.0+encodedPoint.a)/32.0-512.0;}
float segmentDistance(vec2 p,vec2 a,vec2 b){vec2 ab=b-a;float t=clamp(dot(p-a,ab)/max(dot(ab,ab),.00001),0.0,1.0);return length(p-a-ab*t);}
float coverage(float distance,float radius,float aa){return 1.0-smoothstep(radius-aa,radius+aa,distance);}
vec4 screenOver(vec4 current,vec3 rgb,float alpha){return vec4(1.0-(1.0-current.rgb)*(1.0-rgb*alpha),alpha+current.a*(1.0-alpha));}
vec4 frag () {
  float row=floor(pathData.r+.01),width=pathData.g,strength=pathData.b,count=floor(texture(pathTex,vec2(63.5/64.0,(row+.5)/64.0)).r*255.0+.5);
  vec2 p=uv*vec2(384,768),a=pointAt(0.0,row);float d=10000.0;
  for(int i=1;i<63;i++){if(float(i)>=count)break;vec2 b=pointAt(float(i),row);d=min(d,segmentDistance(p,a,b));a=b;}
    float aa=max(fwidth(d)*.65,.45);
  float outer=params.x>29.0?.12:.24;
  vec4 col=vec4(0.0);
  col=screenOver(col,vec3(106,39,225)/255.0,min(outer,strength*outer)*coverage(d,width*4.5,aa));
  col=screenOver(col,vec3(161,72,255)/255.0,min(.58,strength*.65)*coverage(d,width*1.8,aa));
  col=screenOver(col,vec3(218,163,255)/255.0,min(1.0,strength)*coverage(d,width*.85,aa));
  col=screenOver(col,vec3(255,239,255)/255.0,min(1.0,strength*1.15)*coverage(d,width*.5,aa));
  return col*pathData.a;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

