attribute vec2 a_texCoord;
attribute vec4 a_color;
varying vec2 uv;
varying vec4 pathData;
vec4 vert () { uv=a_texCoord; pathData=a_color; return cc_matViewProj*vec4(a_position,1.0); }
void main() { gl_Position = vert(); }

